export const coastalViews={
 'coast-weather':[['freeze','Freeze–thaw'],['chemical','Chemical'],['roots','Biological'],['slide','Slide'],['slump','Slump']],
 'coast-sediment':[['abrasion','Abrasion'],['attrition','Attrition'],['hydraulic','Hydraulic action'],['solution','Solution'],['traction','Traction'],['saltation','Saltation'],['suspension','Suspension'],['drift-right','Drift right'],['drift-left','Drift left'],['deposition','Deposition']],
 'coast-waves':[['constructive','Constructive'],['destructive','Destructive'],['discordant','Discordant'],['concordant','Concordant'],['weakness','Joints & faults']],
 'coast-weather-data':[['fetch','Wind & fetch'],['exposed','Exposed shore'],['sheltered','Sheltered shore'],['storm','Storm & rain'],['record','Retreat record']],
 'coast-landforms':[['bay','Headlands & bays'],['cave','Cave'],['arch','Arch'],['stack','Stack'],['platform','Cliff retreat']]
};
export const coastalRequirements=Object.fromEntries(Object.entries(coastalViews).map(([k,v])=>[k,v.map(x=>x[0])]));
const text=(x,y,s,size=13)=>`<text x="${x}" y="${y}" font-size="${size}">${s}</text>`;
const arrow=(x,y,a,b,color='#ef9c88')=>`<path d="M${x} ${y}L${a} ${b}" fill="none" stroke="${color}" stroke-width="3" marker-end="url(#coastArrow)"/>`;
const circle=(x,y,r=7,fill='#efb69c')=>`<circle cx="${x}" cy="${y}" r="${r}" fill="${fill}"/>`;
const sea=(t,y=230)=>`<path d="M10 ${y}Q55 ${y-8} 100 ${y}T280 ${y}T430 ${y}V335H10Z" fill="url(#coastSea)"/><path d="M10 ${y}Q${45+t*40} ${y-14} 100 ${y}T280 ${y}T430 ${y}" stroke="#b9e4e9" fill="none" stroke-width="3"/>`;
const cliff='<path d="M40 95H245V270H40Z" fill="url(#coastRock)"/><path d="M40 145H245M40 190H245M40 235H245" stroke="#627c8c" stroke-width="2"/>';
export function coastalScene(kind,selected,t=0){const vs=coastalViews[kind];if(!vs)return '';selected=vs.some(x=>x[0]===selected)?selected:vs[0][0];t=Math.max(0,Math.min(1,Number(t)||0));const u=Math.sin(t*Math.PI),s=selected;let body='',caption='',heading=vs.find(x=>x[0]===s)[1];
 if(kind==='coast-weather'){
  body=cliff+sea(t,275);
  if(s==='slide'||s==='slump'){const slump=s==='slump',dx=t*(slump?60:50),dy=slump?70*t-22*t*t:77*t;body=`<path d="M25 100H235L300 280H25Z" fill="url(#coastRock)"/>${sea(t,280)}<path d="${slump?'M165 100Q150 220 285 265':'M170 100L280 270'}" stroke="#ef9c88" stroke-width="3" stroke-dasharray="6 5" fill="none"/><g transform="translate(${dx} ${dy}) rotate(${slump?-t*20:0} 175 130)"><path d="M175 100H235L268 195 210 175Z" fill="#dfb6a1" stroke="#fff0e2" stroke-width="2"/></g>${arrow(285,130,320,195)}${text(305,118,'Gravity')}${text(35,320,slump?'Curved slip surface · rotating block':'Planar slip surface · sliding block')}`;caption=slump?'A block rotates along a curved slip surface. Saturation and loss of toe support can reduce stability.':'Material moves along a broadly planar slip surface. Gravity drives movement; this is not weathering in place.';}
  else{body+=`<path d="M150 95L${150+u*7} 145 135 175 165 210" stroke="${s==='freeze'?'#b9e4e9':'#233c50'}" stroke-width="${5+u*8}" fill="none"/>`;
   if(s==='freeze'){body+=text(45,65,t<.5?'Water enters the crack':'Ice expands; pressure widens crack')+arrow(125,130,105-u*12,130)+arrow(177,130,197+u*12,130);caption='A repeated freeze–thaw cycle can widen a water-filled crack. This diagram exaggerates expansion and compresses time.';}
   if(s==='chemical'){for(let i=0;i<7;i++)body+=circle(140+i*4,110+((t*140+i*17)%100),3,'#a9dce4');body+=text(40,65,'Water reacts with susceptible minerals')+text(255,180,'Alteration',12);caption='Chemical reactions change susceptible minerals in place. Dissolved material may subsequently be transported in water.';}
   if(s==='roots'){body+=`<path d="M155 90V${120+t*70}m0-15l-25 18m25-40l25 18" stroke="#b3cea1" stroke-width="5" fill="none"/><path d="M135 90Q150 60 170 90" fill="#b3cea1"/>`+text(40,65,'Root growth can widen existing cracks');caption='Roots grow into weaknesses: biological weathering. Root growth is shown at exaggerated speed, not as an instant event.';}
  }
 }
 if(kind==='coast-sediment'){
  if(s.startsWith('drift')){const dir=s==='drift-right'?1:-1,xx=dir===1?90:345;body='<path d="M25 65H415V200H25Z" fill="#c7ab8d"/><path d="M25 200H415V325H25Z" fill="url(#coastSea)"/><path d="M25 200H415" stroke="#f4e4c9" stroke-width="3"/>'+text(35,45,'PLAN VIEW · shoreline →')+text(35,95,'Beach')+text(35,305,'Sea');
   const pts=[[xx,250],[xx+dir*65,135],[xx+dir*65,250],[xx+dir*130,135],[xx+dir*130,250]],z=t*4,i=Math.min(3,Math.floor(z)),f=z-i,p=pts[i],n=pts[i+1];for(let j=0;j<4;j++)body+=arrow(...pts[j],...pts[j+1],j%2?'#b7d9e1':'#ef9c88');body+=circle(p[0]+(n[0]-p[0])*f,p[1]+(n[1]-p[1])*f,9)+text(210,110,'Swash ↗ / ↖',12)+text(210,285,'Backwash downslope',12);caption=`Oblique swash and downslope backwash repeat: net sediment drift ${dir===1?'right':'left'}. Angles are schematic; wave approach controls the alongshore direction.`;
  }else{body=sea(t,115)+'<path d="M25 280H415V335H25Z" fill="#9b8877"/>'+text(30,65,'SIDE VIEW · sediment and water');
   if(['traction','saltation','suspension','deposition'].includes(s)){for(let i=0;i<6;i++){let x=40+((t*300+i*47)%350),y=s==='traction'?270:s==='saltation'?268-48*Math.abs(Math.sin(t*3*Math.PI+i)):s==='deposition'?155+t*110:160+Math.sin(t*5+i)*15;body+=circle(x,y,s==='traction'?10:s==='suspension'?3:6);}body+=arrow(70,100,s==='deposition'?160:320,100);caption={traction:'Large grains roll or slide along the bed: traction.',saltation:'Grains bounce along the bed: saltation.',suspension:'Fine particles are carried within the water: suspension.',deposition:'As transport conditions weaken, some sediment settles onto the bed. Not every grain settles at once.'}[s];}
   if(s==='solution'){body+=text(55,190,'Dissolved load · no visible grains')+arrow(75,225,350,225);caption='Susceptible minerals dissolve. Dissolved material is transported in solution, distinct from fine solid particles in suspension.';}
   if(s==='attrition'){body+=circle(145+u*58,205,18-u*3)+circle(290-u*58,205,18-u*3)+text(60,100,'Particles collide → smaller, rounder');caption='Attrition wears sediment particles as they collide. The cliff itself is not the target in this comparison.';}
   if(s==='abrasion'||s==='hydraulic'){body+=`<path d="M310 70H415V280H310V205L330 180 310 155Z" fill="url(#coastRock)"/>`+arrow(170,175,310,180);if(s==='abrasion')for(let i=0;i<4;i++)body+=circle(110+t*190+i*13,180+i*15,6);else body+=`<path d="M310 180L${330+u*12} 175 350 155" stroke="#c9edf2" stroke-width="${3+u*5}" fill="none"/>`;caption=s==='abrasion'?'Sediment strikes or scrapes the rock surface: abrasion. Compare this target with particle-to-particle attrition.':'Water impact and pressure exploit a crack: hydraulic action. Crack widening is greatly exaggerated.';}
  }
 }
 if(kind==='coast-waves'){
  if(s==='constructive'||s==='destructive'){const construct=s==='constructive',x=80+u*(construct?235:140);body=sea(t,215)+'<path d="M120 315L405 100V335H120Z" fill="#c7ab8d"/>'+`<path d="M90 245L${x} ${315-(x-120)*.75}" stroke="#d1f0ed" stroke-width="15" fill="none"/>`+arrow(200,220,300,145,construct?'#ef9c88':'#92b8c7')+arrow(300,180,185,265,construct?'#92b8c7':'#ef9c88')+text(35,50,construct?'Swash stronger → tends to build beach':'Backwash stronger → tends to remove load')+text(270,120,'Swash',12)+text(190,295,'Backwash',12);caption=construct?'Constructive contrast: swash dominates backwash. Beach building still depends on sediment availability and local conditions.':'Destructive contrast: backwash dominates swash. The model represents a balance, not a fixed wave height or frequency threshold.';}
  else if(s==='weakness'){body=cliff+sea(t,270)+`<path d="M110 95V270M175 95L210 270" stroke="#f8e2d0" stroke-width="3"/><path d="M40 150H175l15 25h55" stroke="#ef9c88" stroke-width="3" fill="none"/>`+text(45,60,'Joint: crack      Fault: displacement')+arrow(300,220,215,205);caption='Joints and faults can focus wave attack. The offset bed across the sloping fault indicates displacement; the vertical joint has no shown offset.';}
  else{const disc=s==='discordant';body=text(30,35,'PLAN VIEW · sea below shoreline')+'<rect x="25" y="50" width="390" height="210" fill="#be9c84"/>';
   if(disc){for(let i=0;i<5;i++)body+=`<rect x="${25+i*78}" y="50" width="78" height="210" fill="${i%2?'#d8b7a0':'#829eab'}"/>`;body+=`<path d="M25 250H100Q140 ${215-u*20} 180 250H255Q295 ${215-u*20} 335 250H415V330H25Z" fill="url(#coastSea)"/>`+text(35,85,'More resistant',12)+text(124,125,'Weaker',12);caption='Discordant: bands meet the coast at roughly right angles. Weaker rock can retreat into bays between more resistant headlands.';}
   else{body+='<rect x="25" y="115" width="390" height="65" fill="#d8b7a0"/><rect x="25" y="180" width="390" height="80" fill="#829eab"/>'+sea(t,260)+`<path d="M215 260V${245-u*50}" stroke="#bce4e8" stroke-width="18"/>`+text(35,85,'Bands parallel to shore',12);caption='Concordant: a resistant outer band may shelter weaker rock. A breach can allow attack behind it; parallel bands do not prevent all erosion.';}
   body+=text(30,315,'Blue-grey = more resistant · tan = weaker',12);
  }
 }
 if(kind==='coast-weather-data'){
  if(s==='record'){const pts=[[65,265],[185,205],[365,115]],z=t*2,i=Math.min(1,Math.floor(z)),f=z-i,p=pts[i],n=pts[i+1];body=arrow(65,265,405,265,'#bcd2db')+arrow(65,265,65,65,'#bcd2db')+'<path d="M65 265L185 205 365 115" fill="none" stroke="#edac97" stroke-width="3"/>'+pts.map(p=>circle(...p,6)).join('')+circle(p[0]+(n[0]-p[0])*f,p[1]+(n[1]-p[1])*f,9,'#e5efef')+text(30,40,'Cumulative retreat (m) · teaching data')+text(30,270,'0')+text(30,210,'6')+text(26,120,'15')+text(60,305,'0')+text(180,305,'2')+text(360,305,'5 years')+text(95,80,'15m ÷ 5years = 3m/year',15);caption='Invented observations: year0=0m, year2=6m, year5=15m. Connecting lines aid reading; they do not establish annual or storm-by-storm rates.';}
  else{body=sea(t,225)+'<path d="M295 120H420V335H295Z" fill="url(#coastRock)"/>';
   if(s==='fetch'){body+=arrow(40,90,290,90)+text(40,65,'Wind blows across uninterrupted water')+text(70,135,'← Fetch →',16);caption='Wind speed, duration and fetch influence wave growth. This arrow shows an uninterrupted water distance, not a measured UK forecast.';}
   if(s==='exposed'||s==='sheltered'){const ex=s==='exposed';body+=arrow(70,120,ex?290:70,ex?120:65)+text(40,55,ex?'Waves approach the coast':'Headland shelters the inner coast');if(!ex)body+='<path d="M210 160H295V205H210Z" fill="#829eab"/>';body+=`<path d="M60 220Q${110+t*50} ${ex?160:206} 200 220" stroke="#c4e4e7" stroke-width="5" fill="none"/>`;caption=ex?'Onshore wave approach leaves this shore more exposed. Compare a sheltered situation; real exposure also depends on offshore bathymetry and coastline shape.':'A headland reduces direct exposure in its lee. Sheltered does not mean no erosion; storms and changing directions can change conditions.';}
   if(s==='storm'){body='<path d="M25 80H250L295 280H25Z" fill="url(#coastRock)"/>'+sea(t,205)+arrow(350,155,260,205)+text(30,40,'Storm waves + raised water + rain');for(let i=0;i<12;i++)body+=`<path d="M${45+i*15} ${70+(t*70+i*9)%70}l-4 10" stroke="#c7e5ed" stroke-width="2"/>`;body+=text(45,315,'Rain can reduce slope stability',13);caption='Storms can combine energetic waves, surge and rainfall. High tide can compound impact; geometry and geology alter the outcome.';}
  }
 }
 if(kind==='coast-landforms'){
  if(s==='bay'){body='<path d="M25 65H415V240H25Z" fill="#829eab"/><path d="M150 65H280V240H150Z" fill="#d8b7a0"/>'+`<path d="M25 255H140Q215 ${230-t*90} 290 255H415V335H25Z" fill="url(#coastSea)"/>`+text(40,45,'PLAN VIEW · differential erosion')+text(175,115,'Weaker',12)+text(35,205,'Headland',12)+text(180,280,'Bay',12)+text(325,205,'Headland',12);caption='Less resistant rock retreats into a bay; resistant headlands remain relatively prominent. Time is compressed and retreat is not calibrated.';}
  else if(s==='platform'){const x=290-t*100;body=sea(t,255)+`<path d="M25 70H${x}V205L${x-18} 218 ${x} 225V285H405V310H25Z" fill="url(#coastRock)"/><path d="M${x} 286H405" stroke="#ead4be" stroke-width="4"/>`+arrow(340,210,x,220)+text(30,45,'SIDE VIEW · repeated notching & collapse')+text(x+8,275,'Platform',12)+text(40,130,'Cliff retreats ←',13);caption='Notching and collapse can move a cliff inland, leaving an eroded rock platform. Debris removal permits renewed attack; high/low tide changes visibility.';}
  else{body=sea(t,260);const hole=s==='cave'?`<path d="M155 260V205Q155 ${160-u*15} 200 185V260Z" fill="#182e40"/>`:s==='arch'?`<path d="M165 260V200Q190 135 230 200V260Z" fill="url(#coastSea)"/>`:'';
   body+=s==='stack'?'<path d="M25 95H125V290H25Z" fill="url(#coastRock)"/><path d="M230 130L280 120 295 290H225Z" fill="url(#coastRock)"/>':`<path d="M25 95H310L330 290H25Z" fill="url(#coastRock)"/>${hole}`;
   body+=arrow(380,245,s==='stack'?290:225,245)+text(30,45,s==='cave'?'Weakness enlarged into a cave':s==='arch'?'Opening through a headland':'Roof collapsed · isolated stack')+text(30,325,'Conditional sequence · no fixed timescale',12);caption={cave:'Hydraulic action and abrasion exploit a weakness. A cave may enlarge; not every cave cuts through a headland.',arch:'Erosion opens a route through the headland. Weathering and further attack may weaken the roof before collapse.',stack:'After roof collapse, a detached pillar can remain as a stack. It can continue eroding; the model is not a named-site prediction.'}[s];}
 }
 return `<svg class="geo-scene" viewBox="0 0 440 350" role="img" aria-label="${heading}: ${caption.replaceAll('&','&amp;').replaceAll('"','&quot;')}"><defs><linearGradient id="coastSea" x2="0" y2="1"><stop stop-color="#6eabbc"/><stop offset="1" stop-color="#365f78"/></linearGradient><linearGradient id="coastRock" x2="1" y2="1"><stop stop-color="#c5b7a4"/><stop offset="1" stop-color="#8a8179"/></linearGradient><marker id="coastArrow" viewBox="0 0 10 10" refX="8" refY="5" markerWidth="6" markerHeight="6" orient="auto-start-reverse"><path d="M0 0L10 5 0 10Z" fill="#ef9c88"/></marker></defs><g fill="#eaf0f1" font-family="sans-serif">${body}</g></svg><p class="geo-caption">${caption}</p>`;
}
